      +'<div class="s-dims one"><label>Quadratmeter<input type="number" inputmode="numeric" id="o-mq" min="'+T.mqMin+'" max="'+T.mqMax+'" step="1"><small>Rechnen Sie 10% für Zuschnitt und Verschnitt dazu</small></label></div></fieldset>';
    h+='<dl class="s-specs"><dt>Format</dt><dd>'+esc(t.fmt.map(function(x){return x.replace('x','×')}).join(' · '))+' cm</dd><dt>Stärke</dt><dd>'+esc(t.sp)+'</dd><dt>Oberfläche</dt><dd>'+esc(t.fin.join(' / ')||'Naturale')+'</dd><dt>Kante</dt><dd>'+(t.rett?'Rektifiziert':'Nicht rektifiziert')+'</dd><dt>Material</dt><dd>'+esc(t.mat)+'</dd>'+(t.extra.length?'<dt>Hinweise</dt><dd>'+esc(t.extra.join(', '))+'</dd>':'')+'</dl>';
