      $$('#o-lot .s-chip',sc).forEach(function(b){b.onclick=function(){c.lot=+b.dataset.v;if(!lotW(curLot(p,c)))c.mq=Math.max(T.mqMin,Math.round(c.mq)||T.mqDefault);upd()}});
      var l=curLot(p,c),fs=$('#o-mqf',sc),mi=$('#o-mq',sc),n=$('#o-lot-n',sc);
