    var fy2=fy+Y+90,T=Math.max(16,15*sc);o+='<text x="'+fx+'" y="'+(fy2-14)+'" class="tc">VORDERANSICHT</text><rect x="'+fx+'" y="'+fy2+'" width="'+X+'" height="'+T+'" fill="#ece7de" stroke="#1a2028" stroke-width="1.2"/>';
    o+='<text x="'+(W-20)+'" y="'+(H-14)+'" text-anchor="end" class="tc">SCHEMATISCHE DARSTELLUNG · MASSE IN CM</text>'+wmLogo(W,H,.5,.05)+'</svg>';return o;
