    if(ex)ex.qty+=qty;else cart.push({key:key,id:p.id,type:p.type,name:p.type==='basin'&&!bQ(p)?'Feinsteinzeug-Waschtisch '+c.w+' cm':p.name,img:p.type==='cube'?svgURI(cubeSVG(c)):p.img,remote:p.imgRemote||p.imgFb||'',sum:cfgSummary(p,c),unit:q.unit,iva:(p.type==='door'||p.type==='tile'||p.type==='basin')?'escl':'incl',mq:p.type==='tile'?c.mq:0,qty:qty,bundle:o.bundle||'',bdisc:o.disc||0,bname:o.bname||''});
