      +'<text x="'+fx+'" y="34" class="tc">EINZELSTÜCK · DRAUFSICHT</text><rect x="'+fx+'" y="'+fy+'" width="'+X+'" height="'+Y+'" fill="#ece7de" stroke="#1a2028" stroke-width="1.2"/>'
